scl:
IF bEnable THEN
    fbEdge(CLK := bSensor);
    IF fbEdge.Q THEN
        nCount := nCount + 1;
    END_IF;
END_IF;

fbSR(S1 := bSet, R := bReset);
fbRS(S := bSet, R1 := bReset);
bLampSR := fbSR.Q1;
bLampRS := fbRS.Q1;

nOld := nVal;
nVal := nVal + nStep;
IF bReset THEN
    nVal := 0;
END_IF;
bHigh := nVal > 6;
bAlarm := bHigh AND bHighPrev;
bHighPrev := bHigh;

fbCount(CU := bPart, R := bReset, PV := 2);
nParts := fbCount.CV;
bBoxFull := fbCount.Q;

CASE nStep OF
    0:  IF bStart THEN nStep := 10; END_IF;
    10: IF bPartIn THEN nStep := 20; END_IF;
    20: IF NOT bPartIn THEN nStep := 30; END_IF;
    30: nStep := 0;
END_CASE;
bConveyor := (nStep = 10) OR (nStep = 20);
